shard.installScript:
#!/bin/bash
# Roundcube Webmail Installation Script for Midnight Panel
set -e
apk add --no-cache curl tar sqlite

cd /mnt/server
mkdir -p db logs temp

if [ -z "${ROUNDCUBE_VERSION}" ] || [ "${ROUNDCUBE_VERSION}" == "latest" ]; then
    ROUNDCUBE_VERSION="1.6.9"
fi

echo "Downloading Roundcube Webmail v${ROUNDCUBE_VERSION} (complete bundle)..."
DOWNLOAD_URL="https://github.com/roundcube/roundcubemail/releases/download/${ROUNDCUBE_VERSION}/roundcubemail-${ROUNDCUBE_VERSION}-complete.tar.gz"
curl -sSL -o roundcube.tar.gz "${DOWNLOAD_URL}"
tar -xzf roundcube.tar.gz --strip-components=1
rm -f roundcube.tar.gz

echo "Initializing local SQLite database..."
if [ ! -f "db/roundcube.db" ]; then
    sqlite3 db/roundcube.db < SQL/sqlite.initial.sql
    chmod 666 db/roundcube.db
fi

RANDOM_DES_KEY=$(cat /dev/urandom | tr -dc 'a-zA-Z0-9' | fold -w 24 | head -n 1)

echo "Writing Roundcube config.inc.php..."
cat << 'EOF' > config/config.inc.php
<?php
$config = [];
$config['db_dsnw'] = 'sqlite:////home/container/db/roundcube.db?mode=0646';
$config['default_host'] = '{{DEFAULT_HOST}}';
$config['default_port'] = {{DEFAULT_PORT}};
$config['smtp_server'] = '{{SMTP_SERVER}}';
$config['smtp_port'] = {{SMTP_PORT}};
$config['smtp_user'] = '%u';
$config['smtp_pass'] = '%p';
$config['support_url'] = '';
$config['product_name'] = '{{PRODUCT_NAME}}';
$config['plugins'] = ['archive', 'zipdownload'];
$config['skin'] = 'elastic';
$config['temp_dir'] = '/home/container/temp';
$config['log_dir'] = '/home/container/logs';
EOF

sed -i "s/{{DEFAULT_HOST}}/${DEFAULT_HOST}/g" config/config.inc.php
sed -i "s/{{DEFAULT_PORT}}/${DEFAULT_PORT}/g" config/config.inc.php
sed -i "s/{{SMTP_SERVER}}/${SMTP_SERVER}/g" config/config.inc.php
sed -i "s/{{SMTP_PORT}}/${SMTP_PORT}/g" config/config.inc.php
sed -i "s/{{PRODUCT_NAME}}/${PRODUCT_NAME}/g" config/config.inc.php
echo "$config['des_key'] = '${RANDOM_DES_KEY}';" >> config/config.inc.php

chmod -R 777 temp logs db
echo "Roundcube Webmail installation completed!"
